package com.atlaspay; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID; @Service class AuthorizationService { private final JdbcTemplate jdbc; AuthorizationService(JdbcTemplate jdbc){this.jdbc=jdbc;} @Transactional public AuthorizationController.AuthorizationResponse authorize(String key, AuthorizationController.AuthorizationRequest r){ var existing=jdbc.query("select decision_id,payment_id,status,reason from authorization_decisions where idempotency_key=?", ps->ps.setString(1,key), (rs,n)->new AuthorizationController.AuthorizationResponse(UUID.fromString(rs.getString(1)),rs.getString(2),rs.getString(3),rs.getString(4))); if(!existing.isEmpty()) return existing.getFirst(); String status=r.amountMinor()>1_000_000?"declined":"approved"; String reason=status.equals("approved")?"issuer_approved":"amount_limit"; UUID id=UUID.randomUUID(); jdbc.update("insert into authorization_decisions(decision_id,idempotency_key,payment_id,issuer_id,amount_minor,currency,status,reason) values (?,?,?,?,?,?,?,?)",id,key,r.paymentId(),r.issuerId(),r.amountMinor(),r.currency(),status,reason); jdbc.update("insert into outbox_events(event_id,event_type,aggregate_id,payload) values (?,?,?,?)",UUID.randomUUID(),"authorization.decided",r.paymentId(),status); return new AuthorizationController.AuthorizationResponse(id,r.paymentId(),status,reason); }}